<template>
    <div class="panel"
        :class="{inner: options.innerpanel}" 
        :style="{width: options._width + 'px', height, left: options.left + 'px', top: options.top + 'px'}"
        ref="panel">
        <div class="panel-container">
            <div class="panel-heading">
                <span class="panel-title">{{options.title}}</span>
                <div class="toolbar" v-if="options.innerpanel">
                    <selectField :options="selectOption" @change="selectChange" :propValue="size" ref="pannerlCheck"></selectField>
                    <slot name="panel-close"><fork /></slot>
                </div>
            </div>
            <div class="panel-body">
                <slot name="panel-body"></slot>
                <iframe v-if="options.src" :src="options.src"></iframe>
                <div class="panel-mask" v-if="options.innerpanel">
                    <div class="direction">
                        <div class="direction-top" @click="$emit('panelTop', options,propIndex)" v-if="options.top !== 0"></div>
                        <div class="direction-bottom" @click="$emit('panelBottom', options,propIndex)"></div>
                        <div class="direction-left" @click="$emit('panelLeft', options,propIndex)" v-if="options.left !== 0"></div>
                        <div class="direction-right" @click="$emit('panelRight', options,propIndex)" v-if="options.right !== 4"></div>
                        <div class="direction-center"></div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import selectField from "../../../template/fields/select.vue";
export default {
    props: {
        options: Object,
        selectOptions: Array,
        defaultHeight: Number,
        propIndex: Number
    },

    components: {
        selectField
    },

    data() {
        return {
            selectOption: {
                type: 'select',
                items: this.selectOptions
            }
        }
    },

    computed: {
        height() {
            let height = parseInt(this.options.height);
            return height ? (height > 2 ? height + 'px' : height * this.defaultHeight + 'px') : null;
        },

        size() {
            return this.options.size + '';
        }
    },

    methods: {
        selectChange() {
            const val = this.$refs.pannerlCheck.value;
            this.$emit('selectChange', this.options, this.$refs.pannerlCheck.getSelectText(val), val);
        }
    }
}
</script>

<style scoped>
.panel {
    margin-bottom: 8px;
    transition: all 0.8s ease-in-out;
}

.panel.inner {
    padding: 5px;
    position: absolute;
}

.panel .panel-container {
    border: 1px solid #D9D9D9;
    border-radius: 4px;
    display: flex;
    flex-direction: column;
    height: 100%;
}

.panel.inner .panel-container {
    box-shadow: 0 0 3px #ccc;
}

.panel.inner > .panel-container {
    border: 1px solid #eee;
}

.panel > .panel-container > .panel-heading {
    height: 30px;
    line-height: 28px;
    background-color: #eee;
    border-bottom: 1px solid #D9D9D9;
}


.panel.inner > .panel-container > .panel-heading {
    background-color: #fff;
    border-bottom: none;
    display: flex;
}

.panel > .panel-container > .panel-heading > .panel-title {
    font-size: 14px;
    color: rgba(0, 0, 0, 0.65);
    padding-left: 16px;
}

.panel.inner > .panel-container > .panel-heading > .panel-title {
    font-size: 12px;
}

.panel > .panel-container > .panel-heading > .toolbar {
    display: flex;
    flex: 1;
    justify-content: flex-end;
    align-items: center;
}

.panel > .panel-container > .panel-heading > .toolbar > .select {
    width: 100px;
    height: 24px;
}

.panel > .panel-container > .panel-body {
    flex: 1;
    min-height: 30px;
    display: flex;
    flex-wrap: wrap;
}

.panel.inner > .panel-container > .panel-body {
    min-height: 30px;
    flex: 1;
    position: relative;
}

.panel.inner > .panel-container>  .panel-body:hover .panel-mask {
    display: flex;
}

.panel.inner > .panel-container > .panel-body > .panel-mask {
    display: none;
    width: 100%;
    height: 100%;
    align-items: center;
    justify-content: center;
}

.panel.inner > .panel-container > .panel-body > .panel-mask > .direction {
    position: relative;
    width: 60px;
    height: 52px;
}

.panel.inner > .panel-container > .panel-body > .panel-mask > .direction > div {
    position: absolute;
    width:0;
    height:0;
}

.panel.inner > .panel-container > .panel-body > .panel-mask > .direction > .direction-center {
    width: 26px;
    height: 22px;
    border: 2px solid #007AFF;
    border-radius: 5px;
    left: 50%;
    top: 50%;
    margin-top: -11px;
    margin-left: -13px;
}

.panel.inner > .panel-container > .panel-body > .panel-mask > .direction > .direction-top {
    /* padding: 5px; */
    cursor: pointer;
    top: 0;
    left: 50%;
    margin-left: -5px;
    border-left: 5px solid transparent;
    border-right: 5px solid transparent;
    border-bottom: 8px solid #D9D9D9;
}

.panel.inner > .panel-container > .panel-body > .panel-mask > .direction > .direction-top:hover {
    border-bottom-color: #007AFF;
}

.panel.inner > .panel-container > .panel-body > .panel-mask > .direction > .direction-bottom {
    cursor: pointer;
    bottom: 0;
    left: 50%;
    margin-left: -5px;
    border-left: 5px solid transparent;
    border-right: 5px solid transparent;
    border-top: 8px solid #D9D9D9 ;
}

.panel.inner > .panel-container > .panel-body > .panel-mask > .direction > .direction-bottom:hover {
    border-top-color: #007AFF;
}

.panel.inner > .panel-container > .panel-body > .panel-mask > .direction > .direction-left {
    cursor: pointer;
    left: 0;
    top: 50%;
    margin-top: -4px;
