    border-top: 5px solid transparent;
    border-right: 8px solid #D9D9D9;
}

.panel.inner > .panel-container > .panel-body > .panel-mask > .direction > .direction-left:hover {
    border-right-color: #007AFF;
}

.panel.inner > .panel-container > .panel-body > .panel-mask > .direction > .direction-right {
    cursor: pointer;
