<template>
    <Modal :options="modal" ref="modal">
        <div class="drag" slot="modal-body">
            <div class="drag-container">
                <panel :options="headerOptions">
                    <checkboxField
                        slot="panel-body"
                        :options="headerOptions.options"
                        :propValue="headerOptions.values"
                        @change="panelChange">
                    </checkboxField>
                </panel>
                <panel :options="bodyOptions" style="flex: 1">
                    <scroll slot="panel-body">
                        <div class="panner-body-container" ref="container">
                            <panel
                                v-for="(item, index) in bodyOptions.panelOptions"
                                :options="item"
                                :key="index"
                                :selectOptions="bodyOptions.selectOptions"
                                :defaultHeight="defaultHeight"
                                :propIndex="index"
                                @panelTop="panelTop"
                                @panelBottom="panelBottom"
                                @panelLeft="panelLeft"
                                @panelRight="panelRight"
                                @selectChange="selectChange">
                                <button @click.stop="close(item.id, index)" title="关闭" slot="panel-close" class="panel-close">
                                    <fork/>
                                </button>
                            </panel>
                        </div>
                    </scroll>
                </panel>
                <div class="drag-footer">
                    <btnGroup :options="btnOptions"></btnGroup>
                </div>
            </div>
            <configMask v-show="saving"/>
        </div>
    </Modal>
</template>

<script>
import Gikam from "../../../../core/gikam-core";
import Modal from "../../../template/modal.vue";
import configMask from "../../../template/mask/mask";
import panel from "./panel.vue";
import btnGroup from "../../../template/buttonGroup.vue";
import checkboxField from "../../../template/fields/checkbox.vue";
export default {
    props: {
        options: Object
    },

    components: {
        Modal,
        panel,
        checkboxField,
        btnGroup,
        configMask
    },

    data() {
        const _this = this;
        return {
            modal: {
                title: '首页配置',
                modal: {
                    trigger: Gikam.emptyFunction
                },
                onResize: _this.initLocation
            },

            btnOptions: {
                items: [
                    {
                        text: '保存',
                        class: 'blue',
                        onClick: _this.saveConfig
                    },
                    {
                        text: '取消',
                        color: 'primary',
                        onClick: function() {
                            _this.$refs.modal.close();
                        }
                    }
                ]
            },

            headerOptions: {
                title: '功能选择',
                options: {
                    field: 'checkbox'
                },
                values: ''
            },

            bodyOptions: {
                title: '面板设置',
                height: 2,
                panelOptions: [],
                selectOptions: [
                    {
                        text: '1×1', value: 1
                    }, {
                        text: '2×1', value: 2
                    }, {
                        text: '1×2', value: 3
                    }, {
                        text: '2×2', value: 4
                    }, {
                        text: '1×3', value: 5
                    }, {
                        text: '2×3', value: 6
                    }, {
                        text: '1×4', value: 7
                    }, {
                        text: '2×4', value: 8
                    }
                ],
            },
            defaultHeight: 150,
            panelWidth: 0,
            saveParams: [],
            saving: false
        }
    },

    mounted() {
        this.getpanelConfig();
    },

    methods: {
        //打开弹框请求配置数据
        getpanelConfig() {
            Gikam.getJson(Gikam.IFM_CONTEXT + '/secure/core/module/item/workspace-panel-user-configs').done(data => {
                const values = [];
                const panelOptions = [];
                if (data.resetDefaultPanelConfig === '1') {
                    this.btnOptions.items.unshift({
                        text: '重置默认布局',
                        onClick: this.resetDefaultPanelConfig
                    });
                }

                data.panelList.forEach((item, index) => {
                    if (item.config) {
                        panelOptions.push(JSON.parse(item.config));
                    } else {
                        let title = null;
                        data.systemPanelList.forEach(list => {
                            if (list.id === item.panelId) {
                                title = list.title;
                            }
                        })
                        panelOptions.push({
                            id: item.panelId,
                            width:1,
                            _width: 0,
                            innerpanel: true,
                            height:1,
                            size: 1,
                            title,
                            position: null,
                            left: index,
                            top: 0,
                            index,
                        })
                    }
                })
                data.systemPanelList.forEach(item => {
                    let checked = 0;
                    data.panelList.some(i => i.panelId === item.id) && (checked = 1);
                    values.push({
                        text: item.title,
                        value: item.id,
                        checked
                    })
                })
                this.headerOptions.values = JSON.stringify(values);
                this.bodyOptions.panelOptions = panelOptions.sort((prev, cur) => {
                    return prev.index - cur.index;
                });
                this.$nextTick(() => {
                    this.initLocation();
                })
           })
        },

        initLocation() {
            this.panelWidth = Math.floor(this.$refs.container.getBoundingClientRect().width - 10) / 4;
            const options = this.bodyOptions.panelOptions.sort((prev, cur) => {
                return prev.index - cur.index;
            });
            options.forEach((item, index) => {
                if (index === 0 && !item.position) {
                    item.position = [0, 0, item.width, item.height];
                } else if (index !== 0 && !item.position) {
                    const prevItem = options[index - 1];
                    let left = 0, top = 0;
                    if (prevItem.position[2] >= 4 || prevItem.position[2] + item.width > 4) {
                        top = this.getItemTop(options, index);
                    } else {
                        left = prevItem.position[2];
                        top = prevItem.position[1];
                    }
                    item.position = [left, top, left + item.width, top + item.height];
                }
                this.handleLocation(item);
            });
        },

        handleLocation(option) {
            if (!option) return;
            option.right = option.position[2];
            option._width = option.width * this.panelWidth;
            option.top = option.position[1] * this.defaultHeight;
            option.left = option.position[0] * this.panelWidth;
        },

        getItemTop(options, index) {
            let max = options[0].position[3];
            options.forEach(item => {
                if (item.position && item.index < index && max < item.position[3]) {
                    max = item.position[3];
                }
            })
            return max;
        },

        panelChange(checked, value) {
            const selected = JSON.parse(value).filter(item => item.checked);
            this.headerOptions.values = value;
            let panelOptions = this.bodyOptions.panelOptions.sort((prev, cur) => {
                return prev.index - cur.index;
            });
            let index = panelOptions.length ? (panelOptions[panelOptions.length - 1].index + 1) : 0;
            panelOptions.forEach(item => {
                index < item.index && (index = item.index + 1);
            })
            panelOptions = panelOptions.filter(item => selected.some(list => list.value === item.id));
            selected.forEach(item => {
                if (!panelOptions.some(list => list.id === item.value)) {
                    panelOptions.push({
                        id: item.value,
                        title: item.text,
                        width: 1,
                        _width: null,
                        height: 1,
                        top: null,
                        left: null,
                        right: null,
                        size: 1,//下拉框默认值
                        innerpanel: true,
                        index
                    })
                }
            })
            this.bodyOptions.panelOptions = panelOptions;
            this.$nextTick(() => {
                this.initLocation();
            })
        },

        selectChange(options, size, val) {
            options.size = val;
            options.height = parseInt(size.substr(0, 1));
            options.width = parseInt(size.substr(-1, 1));
            options.position[2] = options.position[0] + options.width;
            options.position[3] = options.position[1] + options.height;
            const panelOptions = this.bodyOptions.panelOptions.sort((prev, cur) => {
                return prev.index - cur.index;
            });
            if (options.position[2] > 4) {
                options.position[0] = 0;
                options.position[1] = options.index === 0 ? 0 : this.getItemTop(panelOptions, options.index);
                options.position[2] = options.position[0] + options.width;
                options.position[3] = options.position[1] + options.height;
            }

            panelOptions.forEach(item => {
                if (item.index > options.index) {
                    item.position = null;
                }
            })
            this.$nextTick(() => {
                this.initLocation();
                
            })
        },

        close(id, index) {
            const values = JSON.parse(this.headerOptions.values);
            values.forEach(item => {
                item.value === id && (item.checked = 0);
            })
            this.headerOptions.values = JSON.stringify(values);
            this.bodyOptions.panelOptions.splice(index, 1);
            this.$nextTick(() => {
                this.initLocation();
            })
        },

        panelCanMove(item, index, direction) {
            const options = Gikam.extend(true, [], this.bodyOptions.panelOptions);
            for(let i = 0;i < options.length; i++) {
                if (options[i].id !== item.id) {
                    let isCross = null;
                    let isContinue = null;
                    if (direction === 'top') {
                        isCross = (options[i].position[0] === item.position[0] || options[i].position[2] === item.position[2]) || (options[i].position[0] < item.position[2] && options[i].position[2] > item.position[0]);
                        isContinue = options[i].position[3] === item.position[1] && isCross;
                    } else if (direction === 'bottom') {
                        isCross = (options[i].position[0] === item.position[0] || options[i].position[2] === item.position[2]) || (options[i].position[0] < item.position[2] && options[i].position[2] > item.position[0]);
                        isContinue = options[i].position[1] === item.position[3] && isCross;
                    } else if (direction === 'left') {
                        isCross = (options[i].position[1] === item.position[1] || options[i].position[3] === item.position[3]) || (options[i].position[3] < item.position[1] && options[i].position[3] > item.position[1]);
                        isContinue = options[i].position[2] === item.position[0] && isCross;
                    } else if (direction === 'right') {
                        isCross = (options[i].position[1] === item.position[1] || options[i].position[3] === item.position[3]) || (options[i].position[3] < item.position[1] && options[i].position[3] > item.position[1]);
                        isContinue = options[i].position[0] === item.position[2] && isCross;
                    }

                    if (isContinue) {
                        const {title, id, left, top, index : _index} = options[index]
                        options[index].title = options[i].title;
                        options[index].id = options[i].id;
                        options[index].index = options[i].index;
                        options[i].title = title;
                        options[i].id = id;
                        options[i].index = _index;

                        options[index].left = options[i].left;
                        options[i].left = left;
                        options[index].top = options[i].top;
                        options[i].top = top;
                        this.bodyOptions.panelOptions = options;
                        setTimeout(() => {
                            options[i].left = options[index].left;
                            options[index].left = left;
                            options[i].top = options[index].top;
                            options[index].top = top;
                            this.bodyOptions.panelOptions = options;
                        }, 200)
                        return;
                    }
                }
            }

            item.position= item.position.map((x, i) => {
                switch (direction) {
                    case 'top':
                        i % 2 && (x -= 1);
                        break;
                    case 'bottom':
                        i % 2 && (x += 1);
                        break;
                    case 'left':
                        i % 2 === 0 && (x -= 1);
                        break;
                    case 'right':
                        i % 2 === 0 && (x += 1);
                        break;
                }
                return x;
            })
            this.handleLocation(item);
        },

        panelTop(options, index) {
            this.panelCanMove(options, index, 'top');
        },

        panelBottom(options, index) {
            this.panelCanMove(options, index, 'bottom');
        },

        panelLeft(options, index) {
            this.panelCanMove(options, index, 'left');
        },

        panelRight(options, index) {
            this.panelCanMove(options, index, 'right');
        },

        modalClose() {
            this.$refs.modal.close();
        },

        //重置默认配置
        resetDefaultPanelConfig() {
            this.saveConfig().done(() => {
                Gikam.put(Gikam.IFM_CONTEXT + '/secure/core/module/item/workspace-panel-user-configs/defaults/action/reset', Gikam.getJsonWrapper(null, ['', this.saveParams]));
            })
        },

        // 保存配置
        saveConfig() {
            this.saveParams = [];
            this.bodyOptions.panelOptions.forEach(item => {
                this.saveParams.push({
                    panelId: item.id,
                    config: JSON.stringify(item)
                })
            })
            this.saving = true;
            return Gikam.put(Gikam.IFM_CONTEXT + '/secure/core/module/item/workspace-panel-user-configs', Gikam.getJsonWrapper(null, ['', this.saveParams])).done(() => {
                this.saving = false;
            });
        }
    }
}
</script>

<style scoped>
.drag {
    padding: 0 16px 16px;
    height: 100%;
}

.drag .drag-container {
    display: flex;
    flex-direction: column;
    height: 100%
}

.drag .drag-container > .drag-footer {
    height: 25px;
    display: flex;
    justify-content: flex-end;
}

.drag .checkbox-container {
    border: none;
}

.drag .panner-body-container {
    position: relative;
    width: 100%;
    display: flex;
    flex-wrap: wrap;
}

.drag .panner-body-container button.panel-close{
    background-color: transparent;
    border: none;
    outline: none;
    cursor: pointer;
    color: rgba(0, 0, 0, 0.5);
    padding: 5px 16px 3px;
}

.drag .panner-body-container button.panel-close > svg {
    width: 12px;
}

.drag-header > .drag-title > .title-container > .title {
    float: left;
    margin-left: 8px;
    font-size: 12px;
    color: rgba(0, 0, 0, 0.6);
    padding: 2px 5px;
    border-radius: 4px;
    border: 1px solid #ccc;
}
</style>
